type HasResponse<V> = V extends { response: StandardSchema<any, any> } ? true : false

type HtmlLike = string | { isEscaped: true }

type ToResponse<R> =
  Awaited<R> extends infer X
    ? X extends TypedResponse<any, any, any>
      ? X
      : X extends Response
        ? X
        : X extends null | undefined | void
