 * `defineHandler(...)(...)` with validation options, returned by `defineHandler(options)`.
 *
 * @experimental
 */
export interface DefineHandlerWithOptions<
  V extends DefineHandlerOptions<any, any>,
  E extends Env = any,
  P extends string = string,
